package kavungen

import (
	"fmt"
	"go/format"
	"path/filepath"
	"slices"
	"strconv"
	"strings"

	"github.com/jokruger/kavun/core/member"
)

// GeneratedFile is the name of the one generated Go file per package.
const GeneratedFile = "kavun_gen.go"

// generatedHeader opens every generated file; a kavun_gen.go without it is not ours and is never overwritten.
const generatedHeader = "// Code generated by kavun-gen; DO NOT EDIT.\n"

const (
	importCore    = "github.com/jokruger/kavun/core"
	importMembers = "github.com/jokruger/kavun/core/member/members"
	importValue   = "github.com/jokruger/kavun/core/value"
)

// emitGo renders a package's kavun_gen.go: the type tables, the builtins' init and the module's init, in that order.
// The output is gofmt-formatted and depends on nothing but the model, so equal input gives equal bytes.
func emitGo(ctx *Context, m *packageModel) ([]byte, error) {
	// q qualifies a core identifier: bare inside package core, "core.X" anywhere else.
	q := "core."
	if m.pkgName == "core" {
		q = ""
	}

	imports := map[string]bool{}
	var body strings.Builder

	for _, t := range m.types {
		if !t.hasMembers {
			continue // a members-less type (record, module): its page only, no table
		}
		if q != "" {
			imports[importCore] = true
		}
		imports[importMembers] = true
		varName := methodsVar(t.stem)
		fmt.Fprintf(&body, "\n// %s is the %s type's member table,\n// generated from the directives in %s.\n", varName, t.decl.Name, memberSources(t))
		fmt.Fprintf(&body, "var %s = []%sMethod{\n", varName, q)
		members := slices.Clone(t.members)
		slices.SortFunc(members, func(a, b Directive) int { return int(member.Lookup(a.Name)) - int(member.Lookup(b.Name)) })
		for _, d := range members {
			ctor := "NewMethod"
			if d.Pure {
				ctor = "NewPureMethod"
			}
			line := fmt.Sprintf("\tmembers.%s: %s%s(%s, %s),\n", ctx.memberIdents[d.Name], q, ctor, strconv.Quote(d.Template), d.GoFunc)
			if tooLong(line) {
				line = fmt.Sprintf("\tmembers.%s: %s%s(\n\t\t%s,\n\t\t%s,\n\t),\n", ctx.memberIdents[d.Name], q, ctor, strconv.Quote(d.Template), d.GoFunc)
			}
			body.WriteString(line)
		}
		body.WriteString("}\n")
	}

	if m.builtins != nil {
		if q != "" {
			imports[importCore] = true
		}
		body.WriteString("\n// init registers the free builtin functions declared by the //kavun:builtin directives.\n")
		body.WriteString("func init() {\n")
		fmt.Fprintf(&body, "\tfns := map[uint64]*%sBuiltinFunction{\n", q)
		for _, d := range m.builtinFuncs {
			fmt.Fprintf(&body, "\t\t%d: %sNewBuiltinFunction(%s, %s, %s, %t),\n", d.Slot, q, strconv.Quote(d.Name), strconv.Quote(d.Template), d.GoFunc, d.Pure)
		}
		body.WriteString("\t}\n\n")
		fmt.Fprintf(&body, `	for i, fn := range fns {
		id := uint64(%[1]sGlobalSlotBase) + i
		%[1]sBuiltinFunctions[id] = fn
		BuiltinFunctions[fn.Name] = %[1]sBuiltinFunctionValue(id)
	}

	BuiltinFunctionNames = make([]string, 0, len(fns))
	for id := %[1]sGlobalSlotBase; id < %[1]sGlobalSlotBase+%[1]sModuleSlotSize; id++ {
		if fn := %[1]sBuiltinFunctions[id]; fn != nil {
			BuiltinFunctionNames = append(BuiltinFunctionNames, fn.Name)
		}
	}
}
`, q)
	}

	if m.module != nil {
		if q != "" {
			imports[importCore] = true
		}
		imports[importValue] = true
		if len(m.moduleFuncs) > 0 {
			imports[importMembers] = true
		}
		fmt.Fprintf(&body, "\n// init registers the %s module declared by the //kavun:module and //kavun:fn directives.\n", m.module.Name)
		body.WriteString("func init() {\n")
		fmt.Fprintf(&body, "\tm := %sNewModule(value.%s, %s, %t)\n", q, moduleIDConst(m.module.Name), strconv.Quote(m.module.Name), m.module.Pure)
		for _, d := range m.moduleFuncs {
			method := "Fn"
			if d.Pure {
				method = "PureFn"
			}
			line := fmt.Sprintf("\tm.%s(members.%s, %d, %s, %s)\n", method, ctx.memberIdents[d.Name], d.Slot, strconv.Quote(d.Template), d.GoFunc)
			if tooLong(line) {
				line = fmt.Sprintf("\tm.%s(\n\t\tmembers.%s, %d,\n\t\t%s,\n\t\t%s,\n\t)\n", method, ctx.memberIdents[d.Name], d.Slot, strconv.Quote(d.Template), d.GoFunc)
			}
			body.WriteString(line)
		}
		if m.hasExtras {
			fmt.Fprintf(&body, "\t%s(m)\n", extrasFunc)
		}
		body.WriteString("\tif err := m.Register(); err != nil {\n\t\tpanic(err)\n\t}\n}\n")
	}

	var src strings.Builder
	src.WriteString(generatedHeader)
	fmt.Fprintf(&src, "\npackage %s\n", m.pkgName)
	paths := make([]string, 0, len(imports))
	for p := range imports {
		paths = append(paths, p)
	}
	slices.Sort(paths)
	switch len(paths) {
	case 0:
	case 1:
		fmt.Fprintf(&src, "\nimport %s\n", strconv.Quote(paths[0]))
	default:
		src.WriteString("\nimport (\n")
		for _, p := range paths {
			fmt.Fprintf(&src, "\t%s\n", strconv.Quote(p))
		}
		src.WriteString(")\n")
	}
	src.WriteString(body.String())

	out, err := format.Source([]byte(src.String()))
	if err != nil {
		return nil, fmt.Errorf("formatting the generated %s for package %s: %v", GeneratedFile, m.pkgName, err)
	}
	return out, nil
}

// methodsVar names a type's generated table after its root file: "array" → "arrayMethods",
// "int_range" → "intRangeMethods".
func methodsVar(stem string) string {
	parts := strings.Split(stem, "_")
	for i := 1; i < len(parts); i++ {
		if parts[i] != "" {
			parts[i] = strings.ToUpper(parts[i][:1]) + parts[i][1:]
		}
	}
	return strings.Join(parts, "") + "Methods"
}

// memberSources names the files a type's member directives sit in, in name order: "array_members.go", or the root
// "file.go" of a module-owned type, or both.
func memberSources(t *typeModel) string {
	seen := map[string]bool{}
	var names []string
	for _, d := range t.members {
		if n := filepath.Base(d.Pos.Filename); !seen[n] {
			seen[n] = true
			names = append(names, n)
		}
	}
	slices.Sort(names)
	return strings.Join(names, " and ")
}

// maxLine is the longest generated line, a tab counted as four columns; an entry past it is written over several lines
// (a long template), which gofmt keeps.
const maxLine = 120

// tooLong reports whether a generated line, gofmt's key alignment aside, would pass maxLine.
func tooLong(line string) bool {
	return len(strings.ReplaceAll(strings.TrimSuffix(line, "\n"), "\t", "    "))+20 > maxLine
}
